#!/usr/bin/env python3
import pathlib
import sys

patch_lines = sys.stdin.read().splitlines()
assert patch_lines[0] == '*** Begin Patch'
position = 1
while position < len(patch_lines) and patch_lines[position] != '*** End Patch':
    header = patch_lines[position]
    position += 1
    operation, filename = header[4:].split(': ', 1)
    path = pathlib.Path(filename)
    body = []
    while position < len(patch_lines) and not patch_lines[position].startswith('*** '):
        body.append(patch_lines[position])
        position += 1
    if operation == 'Add File':
        assert not path.exists(), filename
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text('\n'.join(line[1:] for line in body) + '\n')
    elif operation == 'Update File':
        content = path.read_text()
        cursor = 0
        hunks = []
        for line in body:
            if line.startswith('@@'):
                hunks.append([])
            else:
                assert hunks, filename
                hunks[-1].append(line)
        for hunk in hunks:
            previous = '\n'.join(line[1:] for line in hunk if line.startswith((' ', '-'))) + '\n'
            replacement = '\n'.join(line[1:] for line in hunk if line.startswith((' ', '+'))) + '\n'
            offset = content.find(previous, cursor)
            assert offset >= 0, f'Context not found in {filename}: {previous[:120]}'
            content = content[:offset] + replacement + content[offset + len(previous):]
            cursor = offset + len(replacement)
        path.write_text(content)
    else:
        raise ValueError(operation)
    print(f'{operation}: {filename}')
