            testReport.addFailure(new TestFailure(descriptor, result.exception))
        }
    }
}

gradle.buildFinished {
    testReport.printFailures()
}

class TestFailureReport {
    String project
    private Map<String, TestClassFailureReport> reports = [:].withDefault { testClassName -> new TestClassFailureReport(className: testClassName) }

    void addFailure(TestFailure testFailure) {
        reports[testFailure.className].testFailures << testFailure
    }

    void printFailures() {
        def failureReports = reports.values().findAll { !it.testFailures.empty }
        if (failureReports.empty) {
            return
        }

        String redX = "\033[1;31m\u2718 \033[0m"
        String heading = "Failed tests for ${project}"
        int headingBoxWidth = heading.length() + 4
        println """
        ${'-' * headingBoxWidth}
        | ${heading} |
        ${'-' * headingBoxWidth}
        """.stripIndent()
        failureReports.each { TestClassFailureReport failureReport ->
            println "- ${failureReport.className} --> ${failureReport.location}"
            failureReport.testFailures.each { TestFailure failure ->
                println "  ${redX}.${failure.testDescription} --> ${failure.location}"
            }
        }
        println "${'-' * headingBoxWidth}"
    }
}

class TestClassFailureReport {
    String className
    List<TestFailure> testFailures = []

    String getLocation() {
        return "(${className.replaceAll(/.*\./, '')}.java:0)"
    }
}

class TestFailure {
    String className
    String testDescription
    String location = 'Unknown'

    TestFailure(TestDescriptor descriptor, Throwable failure) {
        className = descriptor.className
        testDescription = descriptor.displayName
        failure?.stackTrace?.find { it.className == className }?.each {
            location = "(${it.fileName}:${it.lineNumber})"
        }
    }
}
class VersionSpec {
    private static final SortedSet<JavaVersion> LTS_VERSIONS_SORTED_ASCENDING = [
            JavaVersion.VERSION_1_8,
            JavaVersion.VERSION_11,
            JavaVersion.VERSION_17,
            JavaVersion.VERSION_21,
            JavaVersion.VERSION_25,
    ] as SortedSet

    JavaVersion desiredJdkVersion
    JavaVersion desiredSourceCompatibility

    VersionSpec withLowerLtsVersionBoundCompatibleWith(JavaVersion version) {
        JavaVersion ltsVersion = version == null
                ? LTS_VERSIONS_SORTED_ASCENDING.first()
                : LTS_VERSIONS_SORTED_ASCENDING.find { it.isCompatibleWith(version) }
        new VersionSpec(desiredJdkVersion: [desiredJdkVersion, ltsVersion].max(), desiredSourceCompatibility: [desiredSourceCompatibility, ltsVersion].max())
    }

    JavaLanguageVersion getDesiredJavaLanguageVersion() {
        JavaLanguageVersion.of(desiredJdkVersion.majorVersion)
    }

    String describe() {
        "Build JDK[${desiredJdkVersion}] / JVM Compatibility[${desiredSourceCompatibility}]"
    }
}

VersionSpec createVersionSpec() {
    if (isTestBuild) {
        new VersionSpec(desiredJdkVersion: configuredTestJavaVersion, desiredSourceCompatibility: configuredTestJavaVersion)
    } else {
        new VersionSpec(desiredJdkVersion: maxSupportedJavaVersion, desiredSourceCompatibility: minSupportedJavaVersion)
    }
}

